mod tests {
    use callisto_model::{Diagnostic, Report};
    use serde::Deserialize;

    use super::*;

    #[derive(Serialize, Deserialize)]
    struct FakeReport {
        value: u32,
    }

    impl callisto_model::Report for FakeReport {
        const COMMAND: &'static str = "fake-report";

        fn schema_version(&self) -> u32 {
            1
        }

        fn diagnostics(&self) -> &[Diagnostic] {
            &[]
        }
    }

    #[test]
    fn write_document_serializes_pretty_with_trailing_newline() {
        let mut buf = Vec::new();
        write_document(&mut buf, &FakeReport { value: 42 }).unwrap();
        let text = String::from_utf8(buf).unwrap();
        assert!(text.contains("\"value\": 42"), "got:\n{text}");
        assert!(text.ends_with('\n'));
    }

    #[test]
    fn emit_report_injects_command_schema_version_and_dry_run() {
        let mut buf = Vec::new();
        emit_report(&mut buf, &FakeReport { value: 7 }, false).unwrap();
        let text = String::from_utf8(buf).unwrap();
        assert!(text.contains("\"command\": \"fake-report\""), "got:\n{text}");
        assert!(text.contains("\"schemaVersion\": 1"), "got:\n{text}");
        assert!(text.contains("\"dryRun\": false"), "got:\n{text}");
        assert!(text.contains("\"value\": 7"), "got:\n{text}");
    }

    /// The payload's own `schemaVersion` field must not survive alongside the
    /// envelope's -- exactly one `"schemaVersion"` key, not two.
    #[test]
    fn emit_report_does_not_duplicate_schema_version_key() {
        let mut buf = Vec::new();
        emit_report(&mut buf, &FakeReport { value: 1 }, true).unwrap();
        let text = String::from_utf8(buf).unwrap();
        assert_eq!(text.matches("\"schemaVersion\"").count(), 1, "got:\n{text}");
        assert!(text.contains("\"dryRun\": true"), "got:\n{text}");
    }

    /// Against a real closed pipe the raw write fails with `BrokenPipe` (so the test reproduces the condition), and
    /// [`Stdout`] counts the write as done.
    #[cfg(unix)]
    #[test]
    fn stdout_counts_a_write_to_a_closed_pipe_as_done() {
        use std::os::unix::net::UnixStream;

        let (mut writer, reader) = UnixStream::pair().expect("create socket pair");
        drop(reader);

        // The peer's close is not always visible to the very first write, so keep writing until it surfaces.
        let raw_err = (0..64)
            .find_map(|_| writer.write_all(&[0u8; 4096]).err())
            .expect("writing to a closed UnixStream peer must fail");
        assert_eq!(raw_err.kind(), io::ErrorKind::BrokenPipe, "{raw_err:?}");

        let mut sink = Stdout::new(writer);
        let result = sink
            .write_all(b"more data after the pipe broke")
            .and_then(|()| sink.flush());
        assert!(result.is_ok(), "{result:?}");
    }

    /// Only the closed pipe is quiet: any other error reaches the caller.
    #[test]
    fn stdout_returns_other_errors() {
        struct AlwaysFails;
        impl Write for AlwaysFails {
            fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
                Err(io::Error::new(io::ErrorKind::PermissionDenied, "nope"))
            }
            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let result = Stdout::new(AlwaysFails).write_all(b"data");
        assert_eq!(result.unwrap_err().kind(), io::ErrorKind::PermissionDenied);
    }

    #[test]
    fn report_trait_accessors_expose_schema_version_and_diagnostics() {
        let report = FakeReport { value: 1 };
        assert_eq!(report.schema_version(), 1);
        assert!(report.diagnostics().is_empty());
    }

    /// `log_line` routes purely by `OutputFormat` (Json -> stderr, Text ->
    /// stdout); it writes directly to the process's real fds rather than a
    /// caller-supplied writer, so its destination isn't capturable in-process.
    /// This exercises both branches to prove neither panics.
    #[test]
    fn log_line_does_not_panic_for_either_output_format() {
        log_line(OutputFormat::Json, "to stderr").unwrap();
        log_line(OutputFormat::Text, "to stdout").unwrap();
    }
}
use std::collections::BTreeSet;
use std::io::Write;
use std::sync::{Mutex, OnceLock};

/// Writes advisory text to `err` as given: a note, a warning, an error card or a child's echoed output. Never a
/// report, a prompt or text a decision depends on. Best effort: a closed or failing stream cannot change the result.
pub fn advise(err: &mut dyn Write, text: impl std::fmt::Display) {
    // The result is already decided; a lost advisory line cannot change it.
    drop(write!(err, "{text}"));
}

/// Advises `message` on stderr the first time this process sees it; returns whether it was new.
pub(crate) fn note_once(message: String) -> bool {
    // A command can load the workspace several times; the note describes the workspace, not the load.
    static SEEN: OnceLock<Mutex<BTreeSet<String>>> = OnceLock::new();
    let first = SEEN
        .get_or_init(Mutex::default)
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(message.clone());
    if first {
        advise(&mut std::io::stderr(), format_args!("{message}\n"));
    }
    first
}

#[cfg(test)]
mod tests {
    use std::io;

    use super::{advise, note_once};

    #[test]
    fn a_message_prints_once_and_a_different_one_prints_again() {
        assert!(note_once("note: unit-test message A".into()));
        assert!(!note_once("note: unit-test message A".into()));
        assert!(note_once("note: unit-test message B".into()));
    }

    /// `advise` writes its text as given, and returns nothing a caller could propagate when the stream fails.
    #[test]
    fn advise_writes_as_given_and_ignores_a_failing_stream() {
        struct Closed;
        impl io::Write for Closed {
            fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
                Err(io::ErrorKind::BrokenPipe.into())
            }
            fn flush(&mut self) -> io::Result<()> {
                Err(io::ErrorKind::BrokenPipe.into())
            }
        }

        let mut written = Vec::new();
        advise(&mut written, format_args!("note: {}\n", 1));
        assert_eq!(written, b"note: 1\n");
        advise(&mut Closed, "lost");
    }
}
//! The one color/table decision, shared by every command's text-format output.
//!
//! `NO_COLOR` (non-empty) always wins over everything else; otherwise
//! `CLICOLOR_FORCE`/`FORCE_COLOR` force color on (anstream's own auto-detection
//! doesn't see `FORCE_COLOR`, hence checking it explicitly here); otherwise
//! anstream's own TTY auto-detection decides. Color and box-drawing table
//! formatting are never decided independently -- callers gate both off the
//! same [`enabled`] result.

/// Resolves the color/table `ColorChoice` from the real process environment and stdout.
pub fn resolve() -> anstream::ColorChoice {
    resolve_with(&|name| std::env::var(name).ok())
}

#[expect(clippy::disallowed_methods, reason = "only asks whether stdout is a terminal")]
fn resolve_with(var: &dyn Fn(&str) -> Option<String>) -> anstream::ColorChoice {
    if var("NO_COLOR").is_some_and(|v| !v.is_empty()) {
        return anstream::ColorChoice::Never;
    }
    if var("CLICOLOR_FORCE").is_some() || var("FORCE_COLOR").is_some() {
        return anstream::ColorChoice::Always;
    }
    anstream::AutoStream::choice(&std::io::stdout())
}

/// True when color and box-drawing table formatting should render for stdout.
pub fn enabled() -> bool {
    resolve() != anstream::ColorChoice::Never
}

/// The shared stdout sink over an `AutoStream` using the one resolved `ColorChoice`, so any ANSI codes a renderer
/// emits are stripped when color is disabled.
#[expect(clippy::disallowed_methods, reason = "wrapped in the shared stdout sink")]
pub fn stdout() -> crate::output::Stdout<anstream::AutoStream<std::io::Stdout>> {
    crate::output::Stdout::new(anstream::AutoStream::new(std::io::stdout(), resolve()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use anstream::ColorChoice;
    use std::collections::HashMap;

    fn vars(pairs: &[(&str, &str)]) -> HashMap<String, String> {
        pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
    }

    /// `NO_COLOR` set to a non-empty value always disables color, regardless of the force vars.
    #[test]
    fn no_color_non_empty_wins_over_force_vars() {
        let env = vars(&[("NO_COLOR", "1"), ("CLICOLOR_FORCE", "1"), ("FORCE_COLOR", "1")]);
        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Never);
    }

    /// `NO_COLOR` set but empty does not disable color; `CLICOLOR_FORCE` forces it on.
    #[test]
    fn no_color_empty_does_not_suppress_clicolor_force() {
        let env = vars(&[("NO_COLOR", ""), ("CLICOLOR_FORCE", "1")]);
        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
    }

    /// `CLICOLOR_FORCE` alone forces color on.
    #[test]
    fn clicolor_force_forces_color_on() {
        let env = vars(&[("CLICOLOR_FORCE", "1")]);
        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
    }

    /// `FORCE_COLOR` alone forces color on -- anstream's own auto-detection
    /// doesn't see this variable, which is exactly the blind spot this module exists to close.
    #[test]
    fn force_color_forces_color_on() {
        let env = vars(&[("FORCE_COLOR", "1")]);
        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
    }

    /// Neither `NO_COLOR` nor a force var set falls back to anstream's own
    /// auto-detection, which always resolves to a concrete Always/Never, never Auto.
    #[test]
    fn no_env_signal_falls_back_to_concrete_auto_detection() {
        let env: HashMap<String, String> = HashMap::new();
        let choice = resolve_with(&|k| env.get(k).cloned());
        assert_ne!(choice, ColorChoice::Auto);
    }

    /// `enabled()` mirrors `resolve()`: only `Never` disables it.
    #[test]
    fn enabled_matches_resolve_not_never() {
        assert_eq!(enabled(), resolve() != ColorChoice::Never);
    }
}

# Rust Hazard Reference

Patterns are leads, not findings. Confirm a reachable bad outcome in live code and record evidence that rules out the plausible exception. Use `shared/references/hazards/rust-boundaries.md` for boundary taxonomies T7 and T10.

## T8 · False-success mutation

- Signal: a write-like function returns `Ok(())` before the required mutation or acknowledgment occurs.
- Search: write/update/set/publish functions and early `Ok` returns.
- Confirm: the caller cannot distinguish required work from a no-op and proceeds with incorrect state.
- Refute: idempotent success is part of the contract or the caller verifies the resulting state.

## T1 · Discarded input

- Signal: a meaningful public or trait parameter is renamed with `_`, dropped, or never reaches the behavior it configures.
- Confirm: a caller supplies a value whose omission changes the outcome.
- Refute: the signature is imposed by a trait or compatibility boundary and the value is intentionally irrelevant.

## T2 · Silent fallback

- Signal: `unwrap_or*` substitutes a default after parsing, lookup, or I/O failure.
- Confirm: the default hides a state the caller must distinguish.
- Refute: the default is the documented domain value and preserves required behavior.

## T3 · Recoverable panic

- Signal: `unwrap`, `expect`, or `panic!` is reachable in reusable code.
- Confirm: valid external input or a recoverable dependency failure reaches it.
- Refute: the path is an established invariant, test-only code, or process entrypoint policy.

## T4 · Lost error

- Signal: a `Result` is assigned to `_`, dropped, or replaced by success.
- Confirm: failure changes subsequent correctness and no owner observes it.
- Refute: best-effort behavior is explicit and the discarded failure has no required consequence.

## T5 · Arithmetic overflow

- Signal: user- or data-controlled integers participate in unchecked arithmetic near a bound.
- Confirm: a reachable value overflows under the relevant build profile.
- Refute: types, validation, or domain limits prove the operation safe.

## T6 · Unsafe contract gap

- Signal: an `unsafe` block lacks a locally checkable safety contract or relies on an unverified caller invariant.
- Confirm: a reachable input violates the invariant and can cause undefined behavior.
- Refute: the contract is enforced at the boundary and covers every operation in the block.

## T9 · Incomplete or ambiguous variants

- Signal: enum conversion uses a catch-all that rejects a valid variant, or diagnostic identifiers collide where consumers require uniqueness.
- Confirm: a current variant is mishandled or a consumer cannot distinguish outcomes.
- Refute: the source is intentionally open, the fallback is contractual, or duplicate identifiers are documented aliases.

Search broadly enough to find candidates, then cite the exact caller, input, state transition, and failure for every confirmed result.
