pub fn handle(args: ReleaseCommandArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    run(args, global, &mut std::io::stderr())
}

/// `release` with its notes and warnings written to `err`.
pub fn run(args: ReleaseCommandArgs, global: &GlobalArgs, err: &mut dyn std::io::Write) -> Result<ExitCode, CliError> {
    match args.command {
        None => release(&args.packages, args.receipt.as_deref(), global, err),
        Some(ReleaseArgs::Pending(args)) => pending(args, global),
        Some(ReleaseArgs::Plan(args)) => plan(args, global),
        Some(ReleaseArgs::Inspect(args)) => inspect(args, global),
        Some(ReleaseArgs::BuildPython(args)) => build_python(args, global),
        Some(ReleaseArgs::PackNpm(args)) => pack_npm(args, global),
        Some(ReleaseArgs::PackageCargo(args)) => package_cargo(args, global),
        Some(ReleaseArgs::ArtifactManifest(args)) => artifact_manifest(args, global),
        Some(ReleaseArgs::Execute(args)) => execute(args, global),
    }
}

/// Stderr note when a preview's tags have no `origin` to push to; `refusal` says why.
fn tags_unbound_note(refusal: &callisto_graph::error::OriginRefusal) -> String {
    format!("note: {refusal}, so tag operations are unbound; a real `callisto release` needs a hosted remote")
}

/// The version work `callisto version` has pending for a selection, or the error that stopped the check. Advisory: it
/// never fails the command it decorates.
pub(crate) struct PendingWork {
    packages: Vec<ReleasePackageId>,
    unchecked: Option<GraphError>,
}

impl PendingWork {
    pub(crate) fn of(result: Result<Vec<ReleasePackageId>, GraphError>) -> Self {
        match result {
            Ok(packages) => Self {
                packages,
                unchecked: None,
            },
            Err(error) => Self {
                packages: Vec::new(),
                unchecked: Some(error),
            },
        }
    }

    pub(crate) fn diagnostic(&self) -> Option<callisto_model::Diagnostic> {
        pending_version_diagnostic(&self.packages)
    }

    /// One stderr line saying why the check could not run, naming the error code and where to see the cause. Never a
    /// report diagnostic: the pending-work code means work was found.
    pub(crate) fn write_unchecked_note(&self, err: &mut dyn std::io::Write) {
        if let Some(error) = &self.unchecked {
            let code = miette::Diagnostic::code(error).map_or_else(|| "no code".to_owned(), |code| code.to_string());
            advise(
                err,
                format_args!(
                    "note: could not check for pending version work ({code}); run `callisto status` for the cause\n"
                ),
            );
        }
    }

    fn write_notes(&self, err: &mut dyn std::io::Write) {
        if let Some(note) = self.diagnostic() {
            advise(err, format_args!("note: {}\n", note.message));
        }
        self.write_unchecked_note(err);
    }
}

/// The advisory when `callisto version` has work for the selection: a release plans only versions already written.
pub(crate) fn pending_version_diagnostic(
    packages: &[callisto_model::ReleasePackageId],
) -> Option<callisto_model::Diagnostic> {
    if packages.is_empty() {
        return None;
    }
    let names = packages
        .iter()
        .map(|package| format!("`{package}`"))
        .collect::<Vec<_>>();
    Some(callisto_model::Diagnostic {
        code: callisto_model::DiagnosticCode::PendingVersionWork,
        severity: callisto_model::DiagnosticSeverity::Info,
        message: format!(
            "pending version work for {} is not in this plan: run `callisto version` (or merge the release PR) first",
            names.join(", ")
        ),
        package: None,
        path: None,
        escalated_by: None,
        governed_by: None,
    })
}

/// Stderr warning for a tag that exists here but not on `origin`.
fn tag_missing_from_origin_note(tag: &str) -> String {
    format!(
        "warning: tag `{tag}` exists here but not on `origin`, so its release may not have finished: check out the \
         tagged commit and run `callisto release` again, or push the tag if the release is complete"
    )
}

/// Exact stdout when no package has an unreleased version.
pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";

fn release(
    packages: &[String],
    receipt: Option<&std::path::Path>,
    global: &GlobalArgs,
    err: &mut dyn std::io::Write,
) -> Result<ExitCode, CliError> {
    let selections = parse_selections(packages)?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let root = workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    if let Some(route) = ci_release_route(&workspace)?.filter(|_| !global.dry_run) {
        return Err(CliError::ReleaseRequiresCiRoute {
            reason: route.to_string(),
        });
    }
    let mode = if global.dry_run {
        LocalReleaseSource::Preview
    } else {
        LocalReleaseSource::Trusted
    };
    // The one `ls-remote` is network latency; it runs beside the plan rather than before it. Best effort: a tag that
    // never reached `origin` is a release that did not finish, whatever the plan says next.
    let probe = origin_tag_probe(&workspace).ok().flatten();
    let (missing, planned) = std::thread::scope(|scope| {
        let missing = probe.as_ref().map(|probe| scope.spawn(|| probe.missing(&runner)));
        let planned = plan_loaded_release(&workspace, &selections, mode);
        (missing.map(|handle| handle.join().unwrap_or_default()), planned)
    });
    for tag in missing.unwrap_or_default() {
        advise(&mut *err, format_args!("{}\n", tag_missing_from_origin_note(&tag)));
    }
    let plan = match planned {
        Err(error)
            if matches!(
                &error,
                GraphError::ReleaseSelectionInvalid {
                    reason: callisto_graph::error::ReleaseSelectionInvalidReason::NotARelease,
                    ..
                }
            ) =>
        {
            // The version work that would make the selection a release is the answer to the refusal.
            let pending = PendingWork::of(pending_version_work(&workspace, &selections));
            write_release_preview_notes(None, &pending, &mut *err);
            return Err(error.into());
        }
        other => other?,
    };
    if global.dry_run {
        let pending = PendingWork::of(pending_version_work(&workspace, &selections));
        write_release_preview(
            plan.as_ref(),
            global.format,
            pending.diagnostic(),
            &mut crate::output::stdout(),
        )?;
        write_release_preview_notes(plan.as_ref(), &pending, &mut *err);
        return Ok(ExitCode::SUCCESS);
    }
    let Some(plan) = plan else {
        print_nothing_to_release(global)?;
        let pending = PendingWork::of(pending_version_work(&workspace, &selections));
        write_release_preview_notes(None, &pending, &mut *err);
        return Ok(ExitCode::SUCCESS);
    };
    for diagnostic in &plan.diagnostics {
        advise(&mut *err, format_args!("warning: {}\n", diagnostic.message));
    }
    let intent = plan.intent;
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
    // A receipt records only full success; a partial run is recovered by rerunning.
    let receipt = receipt
        .map(|path| OutputFile::new(global.resolve_file_arg(path), global.dry_run, OutputKind::Receipt))
        .transpose()?;
    if let Some(receipt) = &receipt {
        receipt.probe()?;
    }
    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
        return Err(CliError::ReleaseEnvelopeInvalid {
            detail: "a local release source must be a Git commit".to_owned(),
        });
    };
    // A local run is its own orchestration, so both revisions are the source commit.
    let envelope =
        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
            detail: error.to_string(),
        })?;
    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
    let state = execute_release(&capability, &permit, &envelope, None)?;
    let receipt_document =
        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
            detail: error.to_string(),
        })?;
    let receipt_path = receipt.as_ref().map(|receipt| receipt.path().to_path_buf());
    if let Some(receipt) = receipt {
        receipt.commit(&permit, &receipt_document)?;
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut crate::output::stdout(),
            &ReleaseReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => {
            let released = capability.intent().decision.entries.len();
            match &receipt_path {
                Some(path) => emit_line(&format!(
                    "Released {released} package(s); receipt saved to {}",
                    path.display()
                ))?,
                None => emit_line(&format!("Released {released} package(s)"))?,
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

/// Writes a `release --dry-run` preview of `plan`; `init` shows the same one. `pending` joins the JSON diagnostics.
pub(crate) fn write_release_preview(
    plan: Option<&LocalReleasePlan>,
    format: OutputFormat,
    pending: Option<callisto_model::Diagnostic>,
    out: &mut dyn std::io::Write,
) -> Result<(), CliError> {
    match (plan, format) {
        (None, OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            true,
        )?,
        (None, OutputFormat::Text) => writeln!(out, "{NOTHING_TO_RELEASE}")?,
        (Some(plan), OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseDryRunReport {
                intent: plan.intent.clone(),
                diagnostics: plan.diagnostics.iter().cloned().chain(pending).collect(),
            },
            true,
        )?,
        (Some(plan), OutputFormat::Text) => {
            write!(out, "{}", render_release_plan(&plan.intent, crate::color::enabled()))?
        }
    }
    Ok(())
}

/// The notes `release --dry-run` adds to a preview, on stderr.
fn write_release_preview_notes(plan: Option<&LocalReleasePlan>, pending: &PendingWork, err: &mut dyn std::io::Write) {
    if let Some(plan) = plan {
        if let Some(refusal) = &plan.tags_unbound {
            advise(err, format_args!("{}\n", tags_unbound_note(refusal)));
        }
        for diagnostic in &plan.diagnostics {
            advise(err, format_args!("warning: {}\n", diagnostic.message));
        }
    }
    pending.write_notes(err);
}

fn print_nothing_to_release(global: &GlobalArgs) -> Result<(), CliError> {
    match global.format {
        OutputFormat::Json => emit_report(
            &mut crate::output::stdout(),
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,
    }
    Ok(())
}

fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
    packages.iter().map(|raw| parse_release_selection(raw)).collect()
}

/// Parses one `--package` release selection: `eco/name` only, the same grammar as the release decision file.
fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
    callisto_graph::ConfigError::reject_colon_form(raw, "--package").map_err(callisto_graph::GraphError::Config)?;
    match PackageId::parse(raw) {
        Ok(PackageId::Prefixed { ecosystem, name }) => {
            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
                raw: raw.to_string(),
                detail: error.to_string(),
            })
        }
        _ => Err(CliError::ReleasePackageInvalid {
            raw: raw.to_string(),
            detail: "expected an ecosystem-qualified package id, e.g. `cargo/pkg`".to_string(),
        }),
    }
}

/// One-line description of a release operation, shared by both the plain and table renderers.
fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
    match &operation.id().role {
        callisto_model::ReleaseOperationRole::RegistryPublish { registry } => {
            format!("publish to {}", registry.registry_key().display_name())
        }
        callisto_model::ReleaseOperationRole::PlatformPublish { registry, platform } => {
            format!(
                "publish {} to {}",
                platform.name(),
                registry.registry_key().display_name()
            )
        }
        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
            format!("upload {}", slot.asset_name)
        }
        callisto_model::ReleaseOperationRole::ForgePublish => "publish GitHub release".to_owned(),
    }
}

/// Human-readable plan: each package and version, then its operations.
///
/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
/// box-drawing table formatting renders only alongside color, never independently.
fn render_release_plan(intent: &ReleaseIntentV1, use_color: bool) -> String {
    let mut out = String::from("Release plan:\n");
    if use_color {
        out.push_str(&render_release_plan_table(intent));
        return out;
    }
    for entry in &intent.decision.entries {
        out.push_str(&format!("  {} {}\n", entry.package, entry.target_version));
        for operation in intent.operations.iter().filter(|op| op.id().package == entry.package) {
            out.push_str(&format!("    - {}\n", describe_operation(operation)));
        }
    }
    out
}

fn render_release_plan_table(intent: &ReleaseIntentV1) -> String {
    use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};

    let mut table = Table::new();
    // Our `use_color` gate is the sole authority -- never let comfy-table's own
    // TTY probe override it, so a forced/piped stdout still renders styled.
    table.force_no_tty().enforce_styling();
    table.load_style(UTF8_FULL);
    table.set_header(vec!["Package", "Version", "Operations"]);
    for entry in &intent.decision.entries {
        let steps: Vec<String> = intent
            .operations
            .iter()
            .filter(|op| op.id().package == entry.package)
            .map(describe_operation)
            .collect();
        table.add_row(vec![
            Cell::new(entry.package.to_string()),
            Cell::new(entry.target_version.to_string()).fg(Color::Green),
            Cell::new(steps.join("\n")),
        ]);
    }
    format!("{table}\n")
}

/// Exact stdout when every release commit has finished.
pub const NO_PENDING_RELEASES: &str = "No pending releases.";

fn pending(args: ReleasePendingArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let from = args
        .from
        .as_deref()
        .map(CommitSha::parse)
        .transpose()
        .map_err(|error| CliError::ReleasePendingFromInvalid {
            reason: error.to_string(),
        })?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let decision_path = workspace_decision_path(&args.decision, &workspace.root)?;
    let found = pending_releases(
        &workspace,
        &decision_path,
        usize::try_from(args.limit).unwrap_or(usize::MAX),
        from.as_ref(),
    )?;
    match global.format {
        OutputFormat::Json => {
            let releases: Vec<_> = found
                .iter()
                .map(|release| {
                    serde_json::json!({
                        "source": release.source.as_str(),
                        "packages": release
                            .packages
                            .iter()
                            .map(|(package, version)| serde_json::json!({
                                "package": package.to_string(),
                                "version": version.render(),
                            }))
                            .collect::<Vec<_>>(),
                        "missing": release.missing,
                    })
                })
                .collect();
            emit_report(
                &mut crate::output::stdout(),
                &callisto_model::ReleasePendingReport { pending: releases },
                global.dry_run,
            )?;
        }
        OutputFormat::Text if found.is_empty() => emit_line(NO_PENDING_RELEASES)?,
        OutputFormat::Text => {
            emit_line("Pending releases, oldest first:")?;
            for release in &found {
                let packages: Vec<String> = release
                    .packages
                    .iter()
                    .map(|(package, version)| format!("{package} {}", version.render()))
                    .collect();
                emit_line(&format!(
                    "  {}  {}  (missing: {})",
                    &release.source.as_str()[..12],
                    packages.join(", "),
                    release.missing.join(", ")
                ))?;
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

fn refuse_dry_run(command: &'static str, global: &GlobalArgs) -> Result<(), CliError> {
    if global.dry_run {
        return Err(CliError::DryRunRefused { command });
    }
    Ok(())
}

/// Shared steps of the build commands: require a publish for the ecosystem, validate the intent. Callers refuse
/// `--dry-run` first.
fn build_from_intent(
    ecosystem: &'static str,
    intent_path: &Path,
    source_root: Option<&Path>,
    global: &GlobalArgs,
    publishes_nothing: fn(&ReleaseIntentV1) -> bool,
    build: impl FnOnce(&ValidatedReleaseIntent<'_>) -> Result<Vec<String>, GraphError>,
) -> Result<Vec<String>, CliError> {
    let intent = read_intent(&global.resolve_file_arg(intent_path))?;
    if publishes_nothing(&intent) {
        return Err(CliError::ReleaseNoSealablePublishes { ecosystem });
    }
    let runner = CliCommandRunner;
    let source_workspace = load_workspace(&source_global(global, source_root), &runner)?;
    let root = source_workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
    Ok(build(&capability)?)
}

