fn artifact_manifest(args: ReleaseArtifactManifestArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let out = OutputFile::new(
        global.resolve_file_arg(&args.out),
        global.dry_run,
        OutputKind::ArtifactManifest,
    )?;
    let intent = read_intent(&global.resolve_file_arg(&args.intent))?;
    if args.seal_python && callisto_model::python_publishes(&intent).is_empty() {
        return Err(CliError::ReleaseNoSealablePublishes { ecosystem: "Python" });
    }
    if args.seal_npm && callisto_model::npm_publishes(&intent).is_empty() {
        return Err(CliError::ReleaseNoSealablePublishes { ecosystem: "npm" });
    }
    if intent.artifact_slots.is_empty() && !args.seal_python && !args.seal_npm {
        return Err(CliError::ReleaseNoArtifactSlots);
    }
    let artifact_dir = global.resolve_file_arg(&args.artifact_dir);
    let root = artifact_dir.canonicalize().map_err(|source| CliError::Io {
        source,
        path: Some(artifact_dir.clone()),
    })?;
    if !matches!(intent.snapshot.source, callisto_model::SourceIdentity::GitCommit { .. }) {
        return Err(CliError::ReleaseManifestSourceNotGit);
    }
    let mut entries = Vec::with_capacity(intent.artifact_slots.len());
    for slot in &intent.artifact_slots {
        let path = root.join(&slot.asset_name);
        let metadata = std::fs::symlink_metadata(&path).map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err(CliError::ReleaseArtifactNotRegularFile {
                asset: slot.asset_name.to_string(),
                dir: root.display().to_string(),
            });
        }
        let canonical = path.canonicalize().map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
        if !canonical.starts_with(&root) {
            return Err(CliError::ReleaseArtifactEscapesDirectory {
                asset: slot.asset_name.to_string(),
                dir: root.display().to_string(),
            });
        }
        let file = std::fs::File::open(&canonical).map_err(|source| CliError::Io {
            source,
            path: Some(canonical.clone()),
        })?;
        let (digest, byte_length) = ArtifactDigest::from_reader(file).map_err(|source| CliError::Io {
            source,
            path: Some(canonical),
        })?;
        entries.push(ArtifactManifestEntryV1 {
            slot: slot.clone(),
            digest: digest.clone(),
            byte_length,
            attestation: GitHubArtifactAttestationV1 {
                repository: slot.attestation_policy.repository.clone(),
                workflow_path: slot.attestation_policy.workflow_path.clone(),
                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
                subject_digest: digest,
                source_commit: slot.attestation_policy.workflow_commit.clone(),
            },
        });
    }
    let mut distributions = Vec::new();
    if args.seal_python {
        distributions.extend(seal_python_distributions(&intent, &root)?);
    }
    if args.seal_npm {
        distributions.extend(seal_npm_tarballs(&intent, &root)?);
    }
    let manifest = ArtifactManifestV1::with_distributions(&intent, entries, distributions).map_err(|error| {
        CliError::ReleaseManifestInvalid {
            detail: error.to_string(),
        }
    })?;
    let out_path = out.path().to_path_buf();
    let permit = out.permit();
    out.commit(&permit, &manifest)?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut crate::output::stdout(),
            &ReleaseArtifactManifestReport {
                manifest: manifest.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!("Artifact manifest saved to {}", out_path.display()))?,
    }
    Ok(ExitCode::SUCCESS)
}

/// Canonicalizes the nearest existing ancestor of `path` and re-appends the components that do not exist yet.
fn canonicalize_through_missing(path: &Path) -> std::io::Result<PathBuf> {
    let mut missing = Vec::new();
    let mut current = path;
    loop {
        match dunce::canonicalize(current) {
            Ok(base) => return Ok(missing.iter().rev().fold(base, |resolved, name| resolved.join(name))),
            Err(source) if source.kind() == std::io::ErrorKind::NotFound => {
                let (Some(parent), Some(name)) = (current.parent(), current.file_name()) else {
                    return Err(source);
                };
                missing.push(name);
                current = parent;
            }
            Err(source) => return Err(source),
        }
    }
}

/// Decision paths are repository-relative for the diff and show commands, but callers may pass an absolute one; contain it
/// in `root` once here, before anything is applied. The file and its directories may not exist yet; the writer creates them.
pub(crate) fn workspace_decision_path(path: &Path, root: &Path) -> Result<PathBuf, CliError> {
    let invalid = |detail: String| CliError::ReleaseDecisionPathInvalid {
        path: path.display().to_string(),
        detail,
    };
    let located = if path.is_absolute() {
        path.to_path_buf()
    } else {
        root.join(callisto_model::workspace_relative(path).map_err(|error| invalid(error.to_string()))?)
    };
    let canonical = canonicalize_through_missing(&located).map_err(|error| invalid(error.to_string()))?;
    let relative = canonical
        .strip_prefix(root)
        .map_err(|_outside_source| CliError::ReleaseDecisionOutsideSource {
            decision: canonical.display().to_string(),
            root: root.display().to_string(),
        })?
        .to_path_buf();
    if path.as_os_str().to_string_lossy().ends_with(std::path::is_separator) {
        return Err(invalid("names a directory".to_owned()));
    }
    if relative.as_os_str().is_empty() || canonical.is_dir() {
        return Err(invalid("is a directory".to_owned()));
    }
    if relative.starts_with(".git") {
        return Err(invalid("is inside .git".to_owned()));
    }
    callisto_model::workspace_relative(&relative).map_err(|error| invalid(error.to_string()))
}

fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let out = OutputFile::new(global.resolve_file_arg(&args.out), global.dry_run, OutputKind::Intent)?;
    let runner = CliCommandRunner;
    let source_global = source_global(global, args.source_root.as_deref());
    let workspace = load_workspace(&source_global, &runner)?;
    // Before any commit is read: a shallow or SHA-256 repository must report E266 or E265, not a lower-level git error.
    workspace
        .git_access()
        .require_trustable_repository()
        .map_err(callisto_graph::GraphError::from)?;
    let decision = match args.from_release_commit.as_deref() {
        Some(raw) => {
            let commit = callisto_model::CommitSha::parse(raw).map_err(|error| CliError::ReleaseCommitInvalid {
                raw: raw.to_owned(),
                detail: error.to_string(),
            })?;
            let decision_path = args
                .decision
                .as_deref()
                .expect("clap requires --decision alongside --from-release-commit");
            let decision_path = workspace_decision_path(decision_path, &workspace.root)?;
            derive_release_commit_decision(&workspace, &commit, &decision_path)?
        }
        None => {
            let selections = parse_selections(&args.packages)?;
            let inference = callisto_graph::infer::CommitInference;
            let version_plan =
                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
            derive_selected_release_decision(&workspace, &version_plan, &selections)?
        }
    };
    let locator = IgnoreWalkLocator::new(&workspace.root);
    let (intent, diagnostics) = match (
        &workspace.config.product_release,
        &args.orchestration_revision,
        &args.artifact_repository,
    ) {
        (Some(_), Some(revision), Some(repository)) => {
            let workflow_commit = callisto_model::CommitSha::parse(revision).map_err(|error| {
                CliError::ReleaseOrchestrationRevisionInvalid {
                    revision: revision.clone(),
                    detail: error.to_string(),
                }
            })?;
            let repository = callisto_model::GitHubRepository::parse(repository).map_err(|error| {
                CliError::ReleaseArtifactRepositoryInvalid {
                    repository: repository.clone(),
                    detail: error.to_string(),
                }
            })?;
            // A missing forge-repository is the graph's error; only the match lives here.
            if let Some(configured) = workspace
                .config
                .product_release
                .as_ref()
                .and_then(|release| release.forge_repository.as_ref())
                .filter(|configured| **configured != repository)
            {
                return Err(CliError::ReleaseForgeRepositoryMismatch {
                    configured: configured.as_slug(),
                    requested: repository.as_slug(),
                    from_flag: true,
                });
            }
            build_release_intent(
                &workspace.root,
                &locator,
                &runner,
                &decision,
                ExecutionTrustProfileV1::GitCommit,
                Some(&callisto_graph::commands::ArtifactBuildPolicy {
                    repository,
                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
                    workflow_commit,
                }),
            )?
        }
        (Some(_), _, _) => {
            return Err(CliError::ReleaseOrchestrationFlagsRequired);
        }
        (None, revision, repository) => {
            // The release workflow always passes both flags, including for sources predating [release].
            if revision.is_some() || repository.is_some() {
                log_line(
                    global.format,
                    "notice: --orchestration-revision and --artifact-repository ignored: the source has no [release] section; planning with zero artifact slots",
                )?;
            }
            build_release_intent(
                &workspace.root,
                &locator,
                &runner,
                &decision,
                ExecutionTrustProfileV1::GitCommit,
                None,
            )?
        }
    };
    let out_path = out.path().to_path_buf();
    let permit = out.permit();
    out.commit(&permit, &intent)?;
    for diagnostic in &diagnostics {
        advise(
            &mut std::io::stderr(),
            format_args!("warning: {}\n", diagnostic.message),
        );
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut crate::output::stdout(),
            &ReleasePlanReport {
                intent: intent.clone(),
                diagnostics: diagnostics.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!(
            "Wrote release intent {} to {}",
            intent.digest(),
            out_path.display()
        ))?,
    }
    Ok(ExitCode::SUCCESS)
}

fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let value: serde_json::Value = read_json_file(&global.resolve_file_arg(&args.input))?;
    match global.format {
        OutputFormat::Json => write_document(&mut crate::output::stdout(), &value)?,
        OutputFormat::Text => emit_line(&serde_json::to_string_pretty(&value).expect("JSON value serializes"))?,
    }
    Ok(ExitCode::SUCCESS)
}

fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    // Inputs and the receipt destination are checked before the first effect; a provider failure
    // mid-run still leaves landed effects without a receipt, and a rerun adopts them.
    let receipt = OutputFile::new(
        global.resolve_file_arg(&args.receipt),
        global.dry_run,
        OutputKind::Receipt,
    )?;
    let permit = receipt.permit();
    let intent = read_intent(&global.resolve_file_arg(&args.intent))?;
    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
        CliError::ReleaseOrchestrationRevisionInvalid {
            revision: args.orchestration_revision.clone(),
            detail: error.to_string(),
        }
    })?;
    receipt.probe()?;
    let manifest = args
        .artifact_manifest
        .as_deref()
        .map(|path| read_artifact_manifest(&global.resolve_file_arg(path)))
        .transpose()?;
    // The CI executor publishes only what a credential-free job sealed; a plan with none stops before any effect.
    require_sealed_publishes(&intent, manifest.as_ref())?;
    let sealed_files = manifest
        .as_ref()
        .is_some_and(|manifest| !manifest.distributions.is_empty());
    let needs_artifacts = sealed_files || !intent.artifact_slots.is_empty();
    let artifact_dir = args.artifact_dir.as_deref().map(|dir| global.resolve_file_arg(dir));
    let verified_artifacts = match (manifest.as_ref(), artifact_dir.as_deref()) {
        (None, None) if !needs_artifacts => None,
        (Some(manifest), Some(directory)) if needs_artifacts => {
            let runner = CliCommandRunner;
            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
        }
        _ if needs_artifacts => return Err(CliError::ReleaseMissingArtifactInputs),
        _ => return Err(CliError::ReleaseUnexpectedArtifactInputs),
    };
    // The run envelope is minted and cross-checked here, before the first
    // effect, and is then the single authority for every fact it carries.
    let envelope = ReleaseRunEnvelopeV1::new(
        orchestration_revision,
        &intent,
        verified_artifacts
            .as_ref()
            .map(|artifacts| artifacts.manifest().digest()),
    )
    .map_err(|error| CliError::ReleaseEnvelopeInvalid {
        detail: error.to_string(),
    })?;
    let runner = CliCommandRunner;
    let source_global = source_global(global, args.source_root.as_deref());
    let source_workspace = load_workspace(&source_global, &runner)?;
    // A missing forge-repository is the graph's error during intent validation; only the match lives here.
    if let Some(configured) = source_workspace
        .config
        .product_release
        .as_ref()
        .and_then(|release| release.forge_repository.as_ref())
        && let Some(slot) = intent
            .artifact_slots
            .iter()
            .find(|slot| slot.attestation_policy.repository != *configured)
    {
        return Err(CliError::ReleaseForgeRepositoryMismatch {
            configured: configured.as_slug(),
            requested: slot.attestation_policy.repository.as_slug(),
            from_flag: false,
        });
    }
    // The workspace root, resolved exactly as `plan` resolves it. Executing
    // from a subdirectory must reach the same root, not the process cwd.
    let root = source_workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
    let state = execute_release(&capability, &permit, &envelope, verified_artifacts.as_ref())?;
    let receipt_document =
        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
            detail: error.to_string(),
        })?;
    let receipt_path = receipt.path().to_path_buf();
    receipt.commit(&permit, &receipt_document)?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut crate::output::stdout(),
            &ReleaseExecuteReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!("Release receipt saved to {}", receipt_path.display()))?,
    }
    Ok(ExitCode::SUCCESS)
}

fn source_global(global: &GlobalArgs, source_root: Option<&std::path::Path>) -> GlobalArgs {
    let mut source = global.clone();
    if let Some(root) = source_root {
        source.cwd = global.resolve_file_arg(root);
    }
    source
}

fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
    let value: serde_json::Value = read_json_file(path)?;
    // A stale intent is the expected failure after a schema bump; name it
    // before serde reports it as an opaque parse error.
    let found = &value["schemaVersion"];
    if found != &serde_json::json!(ReleaseIntentV1::SCHEMA_VERSION) {
        return Err(CliError::ReleaseIntentSchemaUnsupported {
            path: path.to_path_buf(),
            found: found.to_string(),
            expected: ReleaseIntentV1::SCHEMA_VERSION,
        });
    }
    let wire: ReleaseIntentV1Wire = serde_json::from_value(value).map_err(|error| CliError::ReleaseIntentInvalid {
        path: path.display().to_string(),
        detail: error.to_string(),
    })?;
    Ok(ReleaseIntentV1::from_wire(wire)?)
}

fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
    let value: serde_json::Value = read_json_file(path)?;
    serde_json::from_value(value).map_err(|error| CliError::ArtifactManifestFileInvalid {
        path: path.display().to_string(),
        detail: error.to_string(),
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn parse_release_selection_rejects_the_colon_form_and_names_the_slash_form() {
        let err = super::parse_release_selection("cargo:pkg").unwrap_err();
        let rendered = format!("{err:?}");
        assert!(
            rendered.contains("ColonReference") && rendered.contains("cargo/pkg"),
            "{rendered}"
        );
        assert!(super::parse_release_selection("cargo/pkg").is_ok());
    }

    #[test]
    fn parse_release_selection_rejects_a_bare_name() {
        let err = super::parse_release_selection("pkg").unwrap_err();
        assert!(matches!(err, CliError::ReleasePackageInvalid { .. }));
    }

    use callisto_model::{
        RegistryBindingDigest, RegistryBindingId, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason,
        ReleaseInputSnapshotV1, ReleaseOperation, ReleasePackageId, ReleasePackageInputV1, SemanticInputDigest,
        SourceIdentity, Version, VersionGrammar,
    };
    use miette::Diagnostic as _;

    use super::*;

    fn sample() -> ReleaseIntentV1 {
        let package = ReleasePackageId::new(callisto_model::Ecosystem::Cargo, "demo").unwrap();
        let version = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
        let binding =
            RegistryBindingId::new("crates-io", RegistryBindingDigest::parse(&"a".repeat(64)).unwrap()).unwrap();
        let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), binding, vec![]).unwrap();
        let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
        let release =
            ReleaseOperation::forge_release(package.clone(), version.clone(), vec![tag.id().clone()]).unwrap();
        let published =
            ReleaseOperation::forge_publish(package.clone(), version.clone(), vec![release.id().clone()]).unwrap();
        let operations = vec![publish, tag, release, published];
        let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
            package: package.clone(),
            target_version: version,
            reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
        }])
        .unwrap();
        let snapshot = ReleaseInputSnapshotV1::new(
            SourceIdentity::GitCommit {
                sha: callisto_model::CommitSha::parse(&"b".repeat(40)).unwrap(),
            },
            vec![ReleasePackageInputV1 {
                package,
                fingerprint: SemanticInputDigest::parse(&"c".repeat(64)).unwrap(),
            }],
        )
        .unwrap();
        ReleaseIntentV1::new(
            decision,
            snapshot,
            ExecutionTrustProfileV1::GitCommit,
            operations,
            vec![],
        )
        .unwrap()
    }

    /// A persisted intent file whose operations were hand-edited into an invalid DAG
    /// (here, a duplicate operation id) must surface the domain-specific `ReleaseIntentError`
    /// code, not the generic `E236` a `serde` string error would report.
    #[test]
    fn read_intent_preserves_the_typed_release_intent_error_code() {
        let mut value = serde_json::to_value(sample()).expect("intent serializes");
        let operations = value["operations"].as_array().expect("operations array").clone();
        let duplicate = operations[0].clone();
        value["operations"]
            .as_array_mut()
            .expect("operations array")
            .push(duplicate);

        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("intent.json");
        std::fs::write(&path, serde_json::to_string(&value).expect("json")).expect("write intent");

        let err = read_intent(&path).expect_err("duplicate operation must be rejected");
        assert!(
            matches!(
                err,
                CliError::ReleaseIntent(callisto_model::ReleaseIntentError::DuplicateOperation { .. })
            ),
            "{err:?}"
        );
        assert_eq!(err.code().map(|c| c.to_string()), Some("E290".to_string()));
    }

    #[test]
    fn plan_text_lists_each_package_version_and_operation() {
        let intent = sample();
        let text = render_release_plan(&intent, false);
        assert!(text.starts_with("Release plan:\n"), "{text}");
        for entry in &intent.decision.entries {
            assert!(
                text.contains(&format!("  {} {}\n", entry.package, entry.target_version)),
                "{text}"
            );
        }
        assert_eq!(text.matches("    - ").count(), intent.operations.len(), "{text}");
    }

    /// A registry publish step names the registry's display name
    /// (`crates.io`), not its wire key (`crates-io`).
    #[test]
    fn plan_text_names_registries_by_display_name_not_wire_key() {
        let intent = sample();
        let text = render_release_plan(&intent, false);
        assert!(text.contains("publish to crates.io"), "{text}");
        assert!(!text.contains("crates-io"), "{text}");
    }

    /// `use_color: true` renders the release plan as a box-drawing table.
    #[test]
    fn plan_text_with_color_renders_box_drawing_table() {
        let intent = sample();
        let text = render_release_plan(&intent, true);
        assert!(text.starts_with("Release plan:\n"), "{text}");
        assert!(text.contains('\u{2502}'), "expected a box-drawing char in:\n{text}");
        for entry in &intent.decision.entries {
            assert!(text.contains(&entry.package.to_string()), "{text}");
        }
    }

    /// `use_color: false` never emits box-drawing characters.
    #[test]
    fn plan_text_without_color_has_no_box_drawing_chars() {
        let intent = sample();
        let text = render_release_plan(&intent, false);
        assert!(!text.chars().any(|c| ('\u{2500}'..='\u{257F}').contains(&c)), "{text}");
    }
}

//! `callisto init`: report detected facts, ask only for intent, preview the first release, then write.

