/// Asks the operator questions; a scripted implementation drives tests.
pub trait Prompter {
    /// One of a few fixed `items`.
    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
    /// One of a list of any length, such as the workspace's packages; a typed name is resolved by `by_name`.
    fn pick(&mut self, prompt: &str, items: &[String], by_name: tty::NameLookup<'_>) -> Result<usize, CliError>;
    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
}

struct TerminalPrompter;

impl Prompter for TerminalPrompter {
    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
        Ok(Select::new(prompt, items.to_vec())
            .with_help_message("Up/Down move, Enter selects, type to filter")
            .raw_prompt()?
            .index)
    }

    fn pick(&mut self, prompt: &str, items: &[String], by_name: tty::NameLookup<'_>) -> Result<usize, CliError> {
        tty::pick_one(prompt, items, by_name)
    }

    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
        Ok(Confirm::new(prompt).with_default(default).prompt()?)
    }

    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
        let mut input = Text::new(prompt);
        if let Some(default) = default {
            input = input.with_default(default);
        }
        Ok(input.prompt()?)
    }
}

pub fn handle(args: InitArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    run(
        args,
        global,
        tty::Prompts::detect(global.format),
        &mut TerminalPrompter,
        &mut crate::output::stdout(),
        &mut std::io::stderr(),
        &CliCommandRunner,
    )
}

/// Diagnostics queued while `init` runs. `run` emits whatever is still unshown when `init` fails, so an error never
/// swallows a warning that explains it.
#[derive(Default)]
struct Notes {
    /// Queued and not yet on stderr.
    items: Vec<callisto_model::Diagnostic>,
    shown: Vec<callisto_model::Diagnostic>,
}

impl Notes {
    /// Says the queued notes on stderr, best effort, and moves them to the shown ones; the JSON report carries them.
    fn emit(&mut self, err: &mut dyn Write) {
        advise_diagnostics(&self.items, err);
        self.shown.append(&mut self.items);
    }

    /// Every note, shown or not, for the JSON report; call `emit` first so each reaches stderr once.
    fn take_all(&mut self) -> Vec<callisto_model::Diagnostic> {
        let mut all = std::mem::take(&mut self.shown);
        all.append(&mut self.items);
        all
    }
}

/// Says `diagnostics` on stderr, best effort: the JSON report carries them too.
fn advise_diagnostics(diagnostics: &[callisto_model::Diagnostic], err: &mut dyn Write) {
    let mut text = Vec::new();
    render::render_diagnostics(diagnostics, None, &mut text).expect("rendering to memory cannot fail");
    advise(err, String::from_utf8_lossy(&text));
}

/// `init` against explicit terminal state (`prompts` is `Some` when it may ask questions), prompter, output streams, and
/// command runner.
pub fn run<R: CommandRunner>(
    args: InitArgs,
    global: &GlobalArgs,
    prompts: Option<tty::Prompts>,
    prompter: &mut dyn Prompter,
    out: &mut dyn Write,
    err: &mut dyn Write,
    runner: &R,
) -> Result<ExitCode, CliError> {
    let mut notes = Notes::default();
    let result = run_queued(
        args, global, prompts, prompter, &mut *out, &mut *err, runner, &mut notes,
    );
    if result.is_err() {
        notes.emit(err);
    }
    result
}

#[expect(clippy::too_many_arguments, reason = "init's explicit streams plus the note queue")]
fn run_queued<'a, R: CommandRunner>(
    args: InitArgs,
    global: &GlobalArgs,
    prompts: Option<tty::Prompts>,
    prompter: &mut dyn Prompter,
    out: &'a mut dyn Write,
    err: &'a mut dyn Write,
    runner: &R,
    notes: &mut Notes,
) -> Result<ExitCode, CliError> {
    validate_flags(&args)?;
    let interactive = prompts.is_some();
    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
    let (root, no_root) = match workspace_root(global, runner) {
        Ok(root) => (root, None),
        Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
            toplevel.clone(),
            Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
        ),
        Err(error) => return Err(error),
    };
    let locator = IgnoreWalkLocator::new(&root);
    if args.workflow && scaffold::is_initialized(&root)? {
        // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
        // The forge and product flags already require an artifact target.
        if args.versioning.is_some() || !args.artifact_targets.is_empty() {
            return Err(GraphError::InitAlreadyInitialized {
                path: root.join("callisto.toml"),
            }
            .into());
        }
        return run_workflow_only(&root, &locator, global, out, err, runner);
    }
    let facts = scaffold::detect(&root, &locator, runner)?;
    if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
        return Err(error.into());
    }
    let json = global.format == OutputFormat::Json;
    // JSON keeps stdout for the report.
    macro_rules! human {
        () => {
            if json {
                &mut *err
            } else {
                &mut *out
            }
        };
    }
    write_facts(&facts, human!())?;

    if facts.origin.is_none() {
        if args.workflow {
            return Err(CliError::InitFlagRequiresOrigin {
                flag: "workflow",
                not_hosted: facts.origin_not_hosted,
            });
        }
        if !args.artifact_targets.is_empty() {
            return Err(CliError::InitFlagRequiresOrigin {
                flag: "artifact-target",
                not_hosted: facts.origin_not_hosted,
            });
        }
    }
    if !interactive && !args.yes {
        let mut missing = vec!["--yes"];
        missing.extend(missing_flags(&args, &facts));
        return Err(CliError::InitRequiresYes { missing });
    }
    if args.yes {
        let missing = missing_flags(&args, &facts);
        if !missing.is_empty() {
            return Err(CliError::InitMissingFlags { missing });
        }
    }
    let requested = requested_release(&args, &facts)?;
    let prompting = interactive && !args.yes;
    let migration = changesets::migrate(&facts.root, &facts);
    // A dry run writes nothing, so it previews with the warning instead of refusing.
    let refusing = !migration.public_scoped.is_empty() && !args.yes && !global.dry_run;
    // Queued first so a refusal below still shows them; the refusal itself names the access hazard.
    notes.items.extend(migration.diagnostics_unless_refused(refusing));
//! Which package owned a shared name at an earlier commit, judged by the manifests that commit contained.

use std::collections::{BTreeSet, HashMap};
use std::path::{Path, PathBuf};

use callisto_manifests::read_identity;
use callisto_model::vcs::{GitAccess, Pathspec};
use callisto_model::{Ecosystem, ManifestFormat, Package};

use crate::commands::git_batch::{batch_blobs, BatchBlob};
use crate::error::GraphError;
use crate::IdentityIndex;

/// The ecosystems with a manifest declaring a name at a revision, for every (revision, name) already read, the names a
/// revision may still be asked about, and the manifest texts read so far.
#[derive(Default)]
pub(crate) struct Rosters {
    declaring: HashMap<(String, String), BTreeSet<Ecosystem>>,
    expected: HashMap<String, BTreeSet<String>>,
    texts: HashMap<(String, PathBuf), Option<String>>,
}

impl Rosters {
    /// Reads every `(rev, path)` not read yet in one `git cat-file --batch`, so the lookups that follow cost no process.
    ///
    /// A failed batch is not an error: the lookups then read one at a time, as they always could.
    pub(crate) fn prefetch(&mut self, git: &GitAccess<'_>, wanted: &[(String, PathBuf)]) {
        let missing: Vec<&(String, PathBuf)> = wanted.iter().filter(|key| !self.texts.contains_key(*key)).collect();
        let objects: Vec<String> = missing
            .iter()
            .map(|(rev, path)| format!("{rev}:./{}", path.display()))
            .collect();
        let Ok(blobs) = batch_blobs(git.runner(), git.root(), &objects) else {
            return;
        };
        for (key, blob) in missing.into_iter().zip(blobs) {
            let text = match blob {
                BatchBlob::Blob(text) => Some(text),
                BatchBlob::Missing => None,
            };
            self.texts.insert(key.clone(), text);
        }
    }

    /// Names `rev`'s manifests may be asked about, so the first one that has to be searched for reads them all.
    pub(crate) fn expect_names(&mut self, rev: &str, names: impl IntoIterator<Item = String>) {
        self.expected.entry(rev.to_owned()).or_default().extend(names);
    }

    fn manifest_text(&mut self, git: &GitAccess<'_>, rev: &str, path: &Path) -> Result<Option<String>, GraphError> {
        let key = (rev.to_owned(), path.to_path_buf());
        if let Some(known) = self.texts.get(&key) {
            return Ok(known.clone());
        }
        let text = git.read_at(rev, path)?;
        self.texts.insert(key, text.clone());
        Ok(text)
    }

    /// The ecosystems where `rev` held a manifest declaring exactly `name`, the spelling a default tag carries. The
    /// first search at `rev` covers every name expected there: one `git grep` and one batched read of its matches.
    fn declaring_at(&mut self, git: &GitAccess<'_>, rev: &str, name: &str) -> Result<BTreeSet<Ecosystem>, GraphError> {
        let key = (rev.to_owned(), name.to_owned());
        if let Some(known) = self.declaring.get(&key) {
            return Ok(known.clone());
        }
        let mut names = self.expected.remove(rev).unwrap_or_default();
        names.insert(name.to_owned());
        names.retain(|name| !self.declaring.contains_key(&(rev.to_owned(), name.clone())));
        let needles: Vec<&str> = names.iter().map(String::as_str).collect();
        let pathspecs = MANIFESTS.map(|(_, _, file_name)| Pathspec::named_anywhere(file_name));
        let paths = git.files_containing_at(rev, &needles, &pathspecs)?;
        let wanted: Vec<(String, PathBuf)> = paths.iter().map(|path| (rev.to_owned(), path.clone())).collect();
        self.prefetch(git, &wanted);
        let mut found: HashMap<String, BTreeSet<Ecosystem>> = HashMap::new();
        for path in &paths {
            let file_name = path.file_name().and_then(|name| name.to_str());
            let Some((ecosystem, format, _)) = MANIFESTS
                .into_iter()
                .find(|(_, _, manifest)| Some(*manifest) == file_name)
            else {
                continue;
            };
            let Some(text) = self.manifest_text(git, rev, path)? else {
                continue;
            };
            // A manifest that was broken at `rev` simply names nobody.
            let declared = read_identity(format, &text, path)
                .ok()
                .and_then(|identity| identity.name);
            if let Some(declared) = declared.filter(|declared| names.contains(declared)) {
                found.entry(declared).or_default().insert(ecosystem);
            }
        }
        for name in names {
            let ecosystems = found.remove(&name).unwrap_or_default();
            self.declaring.insert((rev.to_owned(), name), ecosystems);
        }
        Ok(self.declaring.get(&key).cloned().unwrap_or_default())
    }
}

const MANIFESTS: [(Ecosystem, ManifestFormat, &str); 3] = [
    (Ecosystem::Cargo, ManifestFormat::CargoToml, "Cargo.toml"),
    (Ecosystem::Npm, ManifestFormat::PackageJson, "package.json"),
    (Ecosystem::Pypi, ManifestFormat::PyprojectToml, "pyproject.toml"),
];

/// Whether `pkg`'s current first manifest held a manifest declaring `name` at `rev`.
fn first_manifest_declares_at(
    git: &GitAccess<'_>,
    rev: &str,
    pkg: &Package,
    name: &str,
    rosters: &mut Rosters,
) -> Result<bool, GraphError> {
    let Some(manifest) = pkg.canonical_manifests().next() else {
        return Ok(false);
    };
    let path = Path::new(&manifest.path);
    let Some(text) = rosters.manifest_text(git, rev, path)? else {
        return Ok(false);
    };
    // A manifest that was broken at `rev` simply names nobody.
    let declared = read_identity(manifest.format, &text, path)
        .ok()
        .and_then(|identity| identity.name);
    Ok(declared.as_deref() == Some(name))
}

/// The one package among `candidates` that owned the bare name `name` at `rev`, if exactly one did.
///
/// A candidate whose current first manifest path held a manifest declaring `name` at `rev` owns it. When none does,
/// the package moved or changed its primary manifest, so ownership is whichever package has a manifest named `name`
/// today in an ecosystem where `rev` also held a manifest named `name`.
pub(crate) fn sole_owner_at<'p>(
    git: &GitAccess<'_>,
    rev: &str,
    name: &str,
    candidates: &[&'p Package],
    identity: &IdentityIndex,
    rosters: &mut Rosters,
) -> Result<Option<&'p Package>, GraphError> {
    let mut owner = None;
    for pkg in candidates {
        if first_manifest_declares_at(git, rev, pkg, name, rosters)? {
            if owner.is_some() {
                return Ok(None);
            }
            owner = Some(*pkg);
        }
    }
    if owner.is_some() {
        return Ok(owner);
    }
    let declaring = rosters.declaring_at(git, rev, name)?;
    let mut holders = candidates.iter().filter(|pkg| {
        declaring.iter().any(|ecosystem| {
            identity
                .native_name(&pkg.id, *ecosystem)
                .is_some_and(|native| native == name)
        })
    });
    let first = holders.next();
    Ok(if holders.next().is_some() { None } else { first.copied() })
}

/// Whether `pkg` can be the package that held the bare name `name` at `rev`.
///
/// False only on evidence of another owner: `rev` held a manifest named `name`, but not in any ecosystem where `pkg`
/// is named `name` today. A revision with no manifest named `name` is no evidence either way.
pub(crate) fn may_have_held_name_at(
    git: &GitAccess<'_>,
    rev: &str,
    name: &str,
    pkg: &Package,
    identity: &IdentityIndex,
    rosters: &mut Rosters,
) -> Result<bool, GraphError> {
    if first_manifest_declares_at(git, rev, pkg, name, rosters)? {
        return Ok(true);
    }
    let declaring = rosters.declaring_at(git, rev, name)?;
    if declaring.is_empty() {
        return Ok(true);
    }
    Ok(declaring.iter().any(|ecosystem| {
        identity
            .native_name(&pkg.id, *ecosystem)
            .is_some_and(|native| native == name)
    }))
}

