#[test]
fn help_flags_propagate_non_broken_pipe_stdout_errors() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("readonly");
    fs::write(&path, "").unwrap();
    let control = bin().arg("help").stdout(File::open(&path).unwrap()).output().unwrap();
    assert_eq!(control.status.code(), Some(1), "explicit help: {control:?}");
    assert!(String::from_utf8_lossy(&control.stderr).contains("E213"));
    for args in [["--help"].as_slice(), &["status", "--help"], &["--version"]] {
        let out = bin().args(args).stdout(File::open(&path).unwrap()).output().unwrap();
        assert_eq!(out.status.code(), Some(1), "args={args:?}; stderr={}", String::from_utf8_lossy(&out.stderr));
        assert!(String::from_utf8_lossy(&out.stderr).contains("E213"));
    }
}

