struct RefuseBranchReview { failed: bool, text: Vec<u8> }
impl Write for RefuseBranchReview {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        if !self.failed && bytes.starts_with(b"  default branch: ") {
            self.failed = true;
            return Err(io::Error::new(io::ErrorKind::PermissionDenied, "injected required branch-review write failure"));
        }
        self.text.extend_from_slice(bytes);
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> { Ok(()) }
}

fn repo() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    init_repo(dir.path());
    fs::write(dir.path().join("Cargo.toml"), "[package]\nname=\"solo\"\nversion=\"0.1.0\"\nedition=\"2021\"\n").unwrap();
    fs::create_dir(dir.path().join("src")).unwrap();
    fs::write(dir.path().join("src/lib.rs"), "").unwrap();
    run_git(dir.path(), &["remote", "add", "origin", "https://github.com/example/tools.git"]);
    dir
}

#[test]
fn required_json_init_branch_review_failure_is_fatal() {
    let dir = repo();
    let mut err = RefuseBranchReview { failed: false, text: Vec::new() };
    let mut out = Vec::new();
    let result = init::run(InitArgs { yes: true, ..Default::default() }, &GlobalArgs { cwd: dir.path().to_owned(), format: OutputFormat::Json, dry_run: false }, None, &mut NoPrompts, &mut out, &mut err, &Offline);
    assert!(err.failed, "the injected failure must be reached");
    assert!(matches!(&result, Err(CliError::Io(e)) if e.kind() == io::ErrorKind::PermissionDenied), "result={result:?}; config_exists={}; workflow_exists={}; stderr={}; stdout={}", dir.path().join("callisto.toml").exists(), dir.path().join(".github/workflows/callisto-release.yml").exists(), String::from_utf8_lossy(&err.text), String::from_utf8_lossy(&out));
    assert!(!dir.path().join("callisto.toml").exists());
}

#[test]
fn flag_help_and_version_closed_stdout_keep_success() {
    for args in [["--help"].as_slice(), &["status", "--help"], &["--version"]] {
        let (read, write) = io::pipe().unwrap(); drop(read);
        let out = bin().args(args).stdout(Stdio::from(write)).output().unwrap();
        assert_eq!(out.status.code(), Some(0), "args={args:?}: {out:?}");
    }
}

