/// Refuses a first release to crates.io of a crate that lacks the metadata crates.io requires.
///
/// Cargo only warns about it locally; crates.io rejects the upload, which can land after other packages published.
fn refuse_a_crate_crates_io_would_reject<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &callisto_model::ReleaseDecisionV1,
) -> Result<(), GraphError> {
    let owners = crate::commands::release_decision::ReleaseOwners::of(workspace);
    for id in first_release_packages(workspace, decision)? {
        let Some(package) = owners.get(&id) else {
            continue;
        };
        if !package.publish_to.contains(&PublishTarget::CratesIo) {
            continue;
        }
        let Some(manifest) = package
            .canonical_manifests()
            .find(|manifest| manifest.format == ManifestFormat::CargoToml)
            .map(|manifest| manifest.path.clone())
        else {
            continue;
        };
        let Some(text) = callisto_manifests::read_manifest_text(&workspace.root)(&manifest)? else {
            continue;
        };
        let document = callisto_manifests::parse_manifest(&manifest, &text)?;
        let root = callisto_manifests::enclosing_workspace_manifest(&workspace.root, &manifest, &document)?;
        let root_document = match root {
            Some(root) => callisto_manifests::read_manifest_text(&workspace.root)(&root)?
                .map(|text| callisto_manifests::parse_manifest(&root, &text))
                .transpose()?,
            None => None,
        };
        let missing = callisto_manifests::missing_crates_io_metadata(&document, root_document.as_ref());
        if !missing.is_empty() {
            return Err(GraphError::ReleaseMetadataMissing {
                package: id.to_string(),
                missing: missing.join(" or "),
            });
        }
    }
    Ok(())
}

/// Refuses a first release whose name another project already owns.
///
/// A package this repository has never tagged has no history here, so a version of it that the registry already holds
/// under a different repository is that project's, not ours; adopting it would tag this commit as their release.
/// A package that has a tag is left alone: its published versions are its own history.
fn refuse_a_name_another_project_owns<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &callisto_model::ReleaseDecisionV1,
    source: &SourceIdentity,
    profile: ExecutionTrustProfileV1,
    mode: LocalReleaseSource,
) -> Result<(), GraphError> {
    let first_releases = first_release_packages(workspace, decision)?;
    // Without an `origin` push URL a preview cannot tell whose repository the registry names.
    if first_releases.is_empty() || (mode == LocalReleaseSource::Preview && workspace.origin()?.preview().is_none()) {
        return Ok(());
    }
    let (_, prepared) =
        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
    match names_taken_by_other_projects(&workspace.root, workspace.runner, &prepared, &first_releases)?
        .into_iter()
        .next()
    {
        Some(taken) => Err(GraphError::ReleaseNameTaken {
            package: taken.package.to_string(),
            version: taken.version,
            registry_repository: taken.registry_repository,
            origin: taken.origin,
        }),
        None => Ok(()),
    }
}

/// Refuses to tag a version the registry already holds while its package has moved on since the commit that set it.
///
/// A release that stopped after publishing leaves exactly this state. A rerun on a later commit would tag code that
/// was never published, so it finishes from the version commit instead. Nothing is observed unless a package moved.
fn refuse_a_published_version_left_behind<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &callisto_model::ReleaseDecisionV1,
    resumable: &std::collections::BTreeSet<ReleasePackageId>,
    source: &SourceIdentity,
    profile: ExecutionTrustProfileV1,
    mode: LocalReleaseSource,
    observation: Observation,
) -> Result<(), GraphError> {
    if observation == Observation::Never {
        return Ok(());
    }
    let moved = super::version_commit::packages_moved_past_their_version(workspace, decision, resumable)?;
    // Without an `origin` push URL a preview cannot observe the registry either.
    if moved.is_empty() || (mode == LocalReleaseSource::Preview && workspace.origin()?.preview().is_none()) {
        return Ok(());
    }
    let (_, prepared) =
        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
    let among = moved.iter().map(|moved| moved.package.clone()).collect();
    let published = published_packages(&workspace.root, workspace.runner, &prepared, &among)?;
    match moved.into_iter().find(|moved| published.contains(&moved.package)) {
        Some(moved) => {
            let (since, fix) = match moved.version_commit {
                Some(commit) => {
                    let short: String = commit.chars().take(12).collect();
                    (
                        format!("{short}, the commit that set it"),
                        format!("Check out {short} (`git checkout --detach {short}`) and run `callisto release` again to finish that release. Releasing from here would tag code that was not published."),
                    )
                }
                None => (
                    "the commit that set it, which this history does not show".to_owned(),
                    "Check out the commit that was published and run `callisto release` again, or tag that commit by hand. Releasing from here could tag code that was not published.".to_owned(),
                ),
            };
            Err(GraphError::ReleasePublishedVersionMoved {
                package: moved.package.to_string(),
                version: moved.version,
                since,
                fix,
            })
        }
        None => Ok(()),
    }
}

/// The plan for every unreleased package (or exactly `selections`) of an already-loaded workspace, e.g. one built from an
/// in-memory config.
///
/// This looks at no registry for a name another project owns, so a caller that must stay offline, such as the plan
/// `init` previews, can use it; [`plan_loaded_release`] does look.
pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    mode: LocalReleaseSource,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    plan_release(workspace, selections, mode, false, Observation::Registries)
}

/// [`plan_workspace_release`] that never observes a registry or the forge: a tagged release is not asked whether it
/// finished, and a version that has moved is not asked whether it was published. For a caller that has no registry
/// to reach, such as the release PR job. It plans exactly `selections`, with their groups.
pub fn plan_workspace_release_offline<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<LocalReleasePlan>, GraphError> {
    plan_release(
        workspace,
        selections,
        LocalReleaseSource::Preview,
        false,
        Observation::Never,
    )
}

/// The one plan derivation behind both `callisto release --dry-run` and `callisto release`, including the registry
/// checks; `None` means nothing is unreleased.
pub fn plan_loaded_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    mode: LocalReleaseSource,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    plan_release(workspace, selections, mode, true, Observation::Registries)
}

/// Whether planning may look at a registry to settle what a previous run did.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Observation {
    Registries,
    Never,
}

fn local_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    profile: ExecutionTrustProfileV1,
    mode: LocalReleaseSource,
) -> Result<SourceIdentity, GraphError> {
    match mode {
        LocalReleaseSource::Preview => Ok(SourceIdentity::GitCommit {
            sha: workspace.git_access().head_sha()?,
        }),
        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead),
    }
}

fn plan_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    mode: LocalReleaseSource,
    check_taken_names: bool,
    observation: Observation,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    let resumable = incomplete_tagged_releases(workspace, mode, observation)?;
    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
    else {
        return Ok(None);
    };
    let profile = ExecutionTrustProfileV1::GitCommit;
    let source = local_source(workspace, profile, mode)?;
    if check_taken_names {
        refuse_a_crate_crates_io_would_reject(workspace, &decision)?;
        refuse_a_name_another_project_owns(workspace, &decision, &source, profile, mode)?;
    }
    refuse_a_published_version_left_behind(workspace, &decision, &resumable, &source, profile, mode, observation)?;
    let remote = match mode {
        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
    };
    // A local run is its own orchestration: slots bind to the source commit.
    let artifact_policy = match (&workspace.config.product_release, &source) {
        (Some(_), SourceIdentity::GitCommit { sha }) => {
            workspace
                .forge_repository_for(remote)?
                .map(|repository| ArtifactBuildPolicy {
                    repository,
                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
                    workflow_commit: sha.clone(),
                })
        }
        _ => None,
    };
    let mut diagnostics = Vec::new();
    // Only a trusted run re-observes the source; a preview takes HEAD's commit as given.
    let recheck = (mode == LocalReleaseSource::Trusted).then_some(ReleaseCheckout::AnyHead);
    let intent = derive_release_intent_unmoved(
        workspace,
        &decision,
        source,
        recheck,
        profile,
        artifact_policy.as_ref(),
        remote,
        &mut diagnostics,
    )?;
    let tags_unbound = if mode == LocalReleaseSource::Preview
        && intent
            .operations
            .iter()
            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
    {
        workspace.origin()?.refusal()
    } else {
        None
    };
    Ok(Some(LocalReleasePlan {
        intent,
        tags_unbound,
        diagnostics,
    }))
}

