pub fn handle(args: ComposePrBodyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let existing_body = match args.existing_body {
        Some(ref s) if s == "-" => {
            let mut stdin_buf = String::new();
            std::io::stdin().read_to_string(&mut stdin_buf)?;
            let clean_stdin = stdin_buf.strip_prefix('\u{FEFF}').unwrap_or(&stdin_buf).to_string();
            Some(clean_stdin)
        }
        other => other,
    };

    let opts = PrBodyOptions {
        existing_body,
        branch: args.branch,
    };

    let report = match args.preview {
        Some(path) => {
            let path = global.resolve_file_arg(&path);
            let text = std::fs::read_to_string(&path).map_err(|source| CliError::Io {
                source,
                path: Some(path.clone()),
            })?;
            let mut preview = callisto_graph::release_preview::ReleasePreview::from_json(&text).map_err(|detail| {
                CliError::ReleaseJsonInvalid {
                    path: path.display().to_string(),
                    detail,
                }
            })?;
            if args.publish_plan {
                let runner = CliCommandRunner;
                let ws = load_workspace(global, &runner)?;
                if let Some(outlook) = callisto_graph::release_preview::publish_outlook_in(&ws, &preview) {
                    preview = preview.with_publish(outlook);
                }
            }
            callisto_graph::commands::render_pr_body_from_preview(&preview, &opts)
        }
        None => {
            let runner = CliCommandRunner;
            let ws = load_workspace(global, &runner)?;
            callisto_graph::commands::compose_pr_body(&ws, &callisto_graph::infer::CommitInference, &opts)?
        }
    };

    match global.format {
        OutputFormat::Json => emit_report(&mut crate::output::stdout(), &report, global.dry_run)?,
        OutputFormat::Text => render::render_compose_pr_body(&report, &mut crate::output::stdout())?,
    }

    Ok(ExitCode::SUCCESS)
}

