fn bin() -> Command { Command::new(env!("CARGO_BIN_EXE_callisto")) }

fn full_stdout() -> (std::os::unix::net::UnixStream, Stdio) {
    use std::os::fd::OwnedFd;
    let (reader, mut writer) = std::os::unix::net::UnixStream::pair().unwrap();
    writer.set_nonblocking(true).unwrap();
    loop {
        match writer.write(&[0; 65536]) {
            Ok(_) => (),
            Err(e) => { assert_eq!(e.kind(), io::ErrorKind::WouldBlock); break; }
        }
    }
    (reader, Stdio::from(OwnedFd::from(writer)))
}

#[test]
fn help_flags_propagate_non_broken_pipe_stdout_errors() {
    let (_reader, writer) = full_stdout();
    let control = bin().arg("help").stdout(writer).output().unwrap();
    assert_eq!(control.status.code(), Some(1), "explicit help: {control:?}");
    assert!(String::from_utf8_lossy(&control.stderr).contains("E213"));
    let mut observed = Vec::new();
    for args in [["--help"].as_slice(), &["status", "--help"], &["--version"]] {
        let (_reader, writer) = full_stdout();
        let out = bin().args(args).stdout(writer).output().unwrap();
        observed.push((args.to_vec(), out.status.code(), String::from_utf8_lossy(&out.stderr).into_owned()));
    }
    assert!(observed.iter().all(|(_, code, err)| *code == Some(1) && err.contains("E213")), "explicit help returned 1/E213 on the same WouldBlock stdout; flags={observed:?}");
}

