struct RefuseBranchReview { failed: bool, text: Vec<u8> }
impl Write for RefuseBranchReview {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        if !self.failed && bytes.starts_with(b"  default branch: ") {
            self.failed = true;
            return Err(io::Error::new(io::ErrorKind::PermissionDenied, "injected required branch-review write failure"));
        }
        self.text.extend_from_slice(bytes);
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> { Ok(()) }
}

