fn required_json_init_branch_review_failure_is_fatal() {
    let control = repo();
    let mut good_out = Vec::new();
    let mut good_err = Vec::new();
    let good = init::run(InitArgs { yes: true, ..Default::default() }, &GlobalArgs { cwd: control.path().to_owned(), format: OutputFormat::Json, dry_run: false }, None, &mut NoPrompts, &mut good_out, &mut good_err, &Offline);
    assert!(good.is_ok(), "{good:?}");
    assert!(control.path().join(".github/workflows/callisto-release.yml").exists());
    let dir = repo();
