    assert!(err.failed, "the injected failure must be reached");
    assert!(matches!(&result, Err(CliError::Io { .. })), "result={result:?}; config_exists={}; workflow_exists={}; warning={}", dir.path().join("callisto.toml").exists(), dir.path().join(".github/workflows/callisto-release.yml").exists(), String::from_utf8_lossy(&err.text).lines().find(|line| line.contains("Skipping the GitHub Actions workflow")).unwrap_or("missing warning"));
    assert!(!dir.path().join("callisto.toml").exists());
}

