pub use callisto_cli::output;

mod live_runner {
    include!("../src/runner.rs");

    #[test]
    fn capture_does_not_treat_an_interrupted_read_as_eof() {
        struct InterruptedOutput { step: usize }
        impl std::io::Read for InterruptedOutput {
            fn read(&mut self, bytes: &mut [u8]) -> std::io::Result<usize> {
                self.step += 1;
                match self.step {
                    1 => { bytes[..7].copy_from_slice(b"before\n"); Ok(7) }
                    2 => Err(std::io::ErrorKind::Interrupted.into()),
                    3 => { bytes[..6].copy_from_slice(b"after\n"); Ok(6) }
                    _ => Ok(0),
                }
            }
        }
        let captured = capture_stream(InterruptedOutput { step: 0 }, false, &[]);
        assert_eq!(captured, "before\nafter\n", "an interrupted read must be retried, or surfaced as a capture failure; it cannot be EOF");
    }
}
